service.method:

SELECT COUNT(*) AS CNT
  FROM SGWGL     
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO       = ${APP_NO} 
       AND APP_NO_SEQ   = ${APP_NO_SEQ}


UPDATE SGWGL SET
    APP_TYPE        = ${APP_TYPE}        
  , APP_SUBJECT     = ${APP_SUBJECT}     
  , APP_CONTENTS    = ${APP_CONTENTS}                 
  , CUST_GW_ID      = ${CUST_GW_ID}
  , CUST_GW_SUBJECT = ${CUST_GW_SUBJECT} 
  , DEL_FLAG        = 'N'                
  , SUX_WKEY1       = ${SUX_WKEY1}       
  , SUX_WKEY2       = ${SUX_WKEY2}       
  , SUX_WKEY3       = ${SUX_WKEY3}       
  , SUX_WKEY4       = ${SUX_WKEY4}       
  , SUX_WKEY5       = ${SUX_WKEY5}       
  , SUX_WKEY6       = ${SUX_WKEY6}       
  , SUX_WKEY7       = ${SUX_WKEY7}       
  , SUX_WKEY8       = ${SUX_WKEY8}       
  , SUX_WKEY9       = ${SUX_WKEY9}       
  , SUX_WKEY10      = ${SUX_WKEY10}      
  , APP_USER_DATE   = ${current.DATE}    
  , APP_USER_TIME   = ${current.TIME}    
  , APP_USER_ID     = ${session.ID  }    
  , APP_USER_AMT    = ${APP_USER_AMT }   
  , CHANGE_DATE     = ${current.DATE}    
  , CHANGE_TIME     = ${current.TIME}    
  , CHANGE_USER_ID  = ${session.ID}      
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO       = ${APP_NO} 
       AND APP_NO_SEQ   = ${APP_NO_SEQ}


SELECT COUNT(*) AS CNT
  FROM SGWLN 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE}
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE}
       AND APP_NO       = ${APP_NO}
       AND APP_NO_SEQ   = ${APP_NO_SEQ}
       AND APP_LINE_SEQ = ${APP_LINE_SEQ}


		UPDATE SGWLN SET
            APP_STAGE       = ${APP_STAGE}      
          , APP_TYPE        = ${APP_TYPE}       
          , APP_METHOD      = ${APP_METHOD}     
          , APP_USER_ID     = ${APP_USER_ID}  
          , CHANGE_DATE     = ${current.DATE}   
          , CHANGE_TIME     = ${current.TIME}   
          , CHANGE_USER_ID  = ${session.ID}     
		 WHERE HOUSE_CODE       = ${session.HOUSE_CODE}
		       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE}
		       AND APP_NO       = ${APP_NO}
		       AND APP_NO_SEQ   = ${APP_NO_SEQ}
		       AND APP_LINE_SEQ = ${APP_LINE_SEQ}


SELECT COUNT( * ) AS CNT
  FROM SGWGL 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO       = ${APP_NO} 
       AND APP_NO_SEQ   = ${APP_NO_SEQ} 
       AND APP_STATUS   = 'R'


SELECT MAX(APP_NO_SEQ) AS APP_NO_SEQ
  FROM SGWGL 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO       = ${APP_NO}


SELECT CURRENT_STAGE
  FROM SGWGL 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO       = ${APP_NO} 
       AND APP_NO_SEQ   = ${APP_NO_SEQ}


SELECT APP_USER_ID
  FROM SGWLN 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE}
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE}
       AND APP_NO       = ${APP_NO}
       AND APP_NO_SEQ   = ${APP_NO_SEQ}
       AND APP_LINE_SEQ = ${APP_LINE_SEQ}
       AND APP_STAGE    = ${APP_STAGE}


DELETE FROM SGWLN 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO       = ${APP_NO} 
       AND APP_NO_SEQ   = ${APP_NO_SEQ} 
       AND (CAST(#DB_OWNER#NVL(APP_LINE_SEQ,'999') AS INT) > CAST(#DB_OWNER#NVL(${DELETE_APP_LINE_SEQ},'999') AS INT)
       		 OR APP_TYPE = ${APP_TYPE}
           )


DELETE FROM SGWLN 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO       = ${APP_NO} 
       AND APP_NO_SEQ   = ${APP_NO_SEQ} 
       AND CONVERT(#DB_OWNER#NVL(APP_LINE_SEQ,'999'), INT) > CONVERT(#DB_OWNER#NVL(${DELETE_APP_LINE_SEQ},'999'), INT)


SELECT APP_NO
	  ,APP_NO_SEQ 
  FROM SGWGL 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND SUX_WKEY1    = $S{SUX_WKEY1 } 
       AND SUX_WKEY2    = $S{SUX_WKEY2 }  
       AND SUX_WKEY3    = $S{SUX_WKEY3 }  
       AND SUX_WKEY4    = $S{SUX_WKEY4 }  
       AND SUX_WKEY5    = $S{SUX_WKEY5 }  
       AND SUX_WKEY6    = $S{SUX_WKEY6 }  
       AND SUX_WKEY7    = $S{SUX_WKEY7 }  
       AND SUX_WKEY8    = $S{SUX_WKEY8 }  
       AND SUX_WKEY9    = $S{SUX_WKEY9 }  
       AND SUX_WKEY10   = $S{SUX_WKEY10}


DELETE FROM SGWLN 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO       = ${APP_NO} 
       AND APP_NO_SEQ   = ${APP_NO_SEQ}


DELETE FROM SGWLN 
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO       = ${APP_NO} 
       AND APP_NO_SEQ   = ${APP_NO_SEQ}
